// coupled-subsystem simulation sketch for: Future Factory Civilization Simulator
const subs = [
  {name:'power', x:0.556, k:0.114},
  {name:'thermal', x:0.646, k:0.16},
  {name:'structural', x:0.517, k:0.14},
  {name:'control', x:0.816, k:0.192},
  {name:'comms', x:0.393, k:0.129},
];
for (let t = 0; t < 60; t++) {
  for (const s of subs) { s.x += s.k * (1 - s.x) - 0.015 * s.x; }
}
const fin = subs.map(s => +s.x.toFixed(4));
console.log(JSON.stringify({subsystems: subs.length, steps: 60,
  finalState: fin, converged: fin.every(v => v > 0 && v < 1.5),
  topic: 'Future Factory Civilization Simulator'}));

